package com.bookstore.exception; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import org.springframework.web.servlet.mvc.support.RedirectAttributes; @ControllerAdvice public class GlobalExceptionHandler{@ExceptionHandler({ResourceNotFoundException.class,InsufficientStockException.class,IllegalArgumentException.class})String business(RuntimeException e,Model m){m.addAttribute("message",e.getMessage());return "error";}@ExceptionHandler(Exception.class)String general(Exception e,Model m){m.addAttribute("message","Unexpected error: "+e.getMessage());return "error";}}